    font-size: 1.75rem;
    font-weight: 700;
}

p.description {
    color: #666;
    margin-bottom: 2rem;
}

.form-field {
    margin-bottom: 1.5rem;
    display: flex;
    flex-direction: column;
}

label {
    font-weight: 600;
    margin-bottom: 0.5rem;
    color: var(--label-color);
}

.required-marker {
    color: var(--error-color);
    margin-left: 2px;
}

input {
    padding: 0.75rem;
    font-size: 1rem;
    border: 1px solid var(--border-color);
    border-radius: 4px;
    transition: border-color 0.2s, box-shadow 0.2s;
}

input:focus {
