    padding: 0.75rem 1.5rem;
    font-size: 1rem;
    font-weight: 600;
    border: none;
    border-radius: 4px;
    cursor: pointer;
    transition: background-color 0.2s;
    width: 100%;
    margin-top: 1rem;
}

.submit-button:hover {
    background-color: var(--primary-hover);
}

.submit-button:focus {
    outline: none;
    box-shadow: var(--focus-ring);
}

/* Accessibility: Ensure contrast for focused inputs */
@media (prefers-reduced-motion: reduce) {
    * {
        transition: none !important;
    }
}
