function createElement(type, props, ...children) {
    const element = document.createElement(type);

    // Add props
    if (props) {
        Object.entries(props).forEach(([key, value]) => {
            if (key === 'className') {
                element.className = value;
            } else if (key.startsWith('on') && typeof value === 'function') {
                element.addEventListener(key.substring(2).toLowerCase(), value);
            } else if (key === 'style' && typeof value === 'object') {
                Object.assign(element.style, value);
            } else {
                element.setAttribute(key, value);
            }
        });
    }

    // Add children
    children.flat().forEach(child => {
        if (child === null || child === undefined) return;
        if (typeof child === 'string' || typeof child === 'number') {
            element.appendChild(document.createTextNode(child));
        } else {
            element.appendChild(child);
        }
    });

    return element;
}

const FormField = ({ label, id, type = "text", required = false, autocomplete, helperText, ...props }) => {
    const inputProps = {
        id,
        name: id,
        type,
        required: required ? true : undefined,
        autocomplete,
        ...props
    };

    if (helperText) {
        inputProps['aria-describedby'] = `${id}-helper`;
    }

    return createElement('div', { className: 'form-field' },
        createElement('label', { htmlFor: id },
            label,
            required && createElement('span', { className: 'required-marker', 'aria-hidden': 'true' }, '*')
        ),
        createElement('input', inputProps),
        helperText && createElement('p', { id: `${id}-helper`, className: 'helper-text' }, helperText)
    );
};

const ContactForm = () => {
    const handleSubmit = (e) => {
        e.preventDefault();
        alert('Form submitted successfully!');
