                 autocomplete: 'tel',
                 helperText: 'Expected format: (555) 000-0000'
             }),
             createElement('button', { type: 'submit', className: 'submit-button' }, 'Send Message')
         )
     );
 };

 // Render the application
 const root = document.getElementById('root');
 root.appendChild(ContactForm());

