     color: var(--text-color);
     background-color: var(--bg-color);
     margin: 0;
     padding: 2rem;
     display: flex;
     justify-content: center;
     align-items: flex-start;
     min-height: 100vh;
 }

 .container {
     background-color: var(--card-bg);
     padding: 2.5rem;
     border-radius: 8px;
     box-shadow: 0 4px 6px rgba(0, 0, 0, 0.1);
     width: 100%;
     max-width: 500px;
 }

 h1 {
     margin-top: 0;
     margin-bottom: 0.5rem;
     font-size: 1.75rem;
     font-weight: 700;
 }

 p.description {
     color: #666;
     margin-bottom: 2rem;
 }

 .form-field {
     margin-bottom: 1.5rem;
     display: flex;
     flex-direction: column;
 }

 label {
     font-weight: 600;
     margin-bottom: 0.5rem;
     color: var(--label-color);
 }

 .required-marker {
     color: var(--error-color);
     margin-left: 2px;
 }

 input {
     padding: 0.75rem;
     font-size: 1rem;
     border: 1px solid var(--border-color);
     border-radius: 4px;
     transition: border-color 0.2s, box-shadow 0.2s;
 }

 input:focus {
     outline: none;
     border-color: var(--primary-color);
     box-shadow: var(--focus-ring);
 }

 .helper-text {
     font-size: 0.875rem;
     color: #666;
     margin-top: 0.25rem;
 }

 .submit-button {
     background-color: var(--primary-color);
     color: white;
     padding: 0.75rem 1.5rem;
     font-size: 1rem;
     font-weight: 600;
     border: none;
     border-radius: 4px;
     cursor: pointer;
     transition: background-color 0.2s;
     width: 100%;
     margin-top: 1rem;
 }

 .submit-button:hover {
     background-color: var(--primary-hover);
 }

 .submit-button:focus {
     outline: none;
     box-shadow: var(--focus-ring);
 }

 /* Accessibility: Ensure contrast for focused inputs */
 @media (prefers-reduced-motion: reduce) {
     * {
         transition: none !important;
     }
 }

